-- Din Felsefesi I, 1. ve 2. hafta: yeniden yazılan Zapoot (20) ve Quiz (15) soruları, ayrı paketler olarak eklenir (eski paketlere dokunulmaz).
-- Kaynak: docs/soru-onerileri/yeni/h01-h02.txt. Aynı soru metni varsa atlanır. 16 Kasım 2026 kullanıcı onayıyla.
do $$
declare v_icerik uuid;
begin
  select id into v_icerik from public.subjects where ad = 'Din Felsefesi I' limit 1;
  if v_icerik is null then raise exception 'Din Felsefesi I içeriği bulunamadı'; end if;
  insert into public.questions (subject_id, soru, dogru, yanlislar, sure_sn, ek)
  select v_icerik, x->>'s', x->>'d', array(select jsonb_array_elements_text(x->'y')), (x->>'t')::int,
         jsonb_build_object('paket', x->>'p', 'konu', x->>'k', 'zorluk', x->>'z', 'bloom', x->>'b')
  from jsonb_array_elements($j$[{"s":"“Din felsefesi” adı 19. yüzyılda literatüre girmiştir. Buna karşın din üzerine felsefî düşünmenin tarihi için hangisi söylenebilir?","d":"Felsefenin kendisi kadar eskidir","y":["Aydınlanma çağında başlamıştır","Orta Çağ skolastiğiyle ortaya çıkmıştır","Modern bilimlerin doğuşuyla başlamıştır"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Terimin kökeni","z":"kolay","b":"Anlama"},{"s":"Bir öğrenci “din felsefesi 1832’de Hegel ile başladı” diyor. Bu görüş hangi ayrımı gözden kaçırmaktadır?","d":"Adın ortaya çıkışı ile konunun varlığı arasındaki ayrımı","y":["Kelâm ile tasavvufun yöntemleri arasındaki ayrımı","Dinin ibadî ile ahlâkî boyutu arasındaki ayrımı","Felsefe ile deneysel bilimin konu ve yöntemleri arasındaki ayrımı"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Terimin kökeni","z":"orta","b":"Analiz"},{"s":"Antik Yunan’da felsefe gelişmişken din felsefesinin olgunlaşmamasını en iyi hangisi açıklar?","d":"Felsefî problemler doğuracak vahiy temelli dinî düşüncenin henüz bulunmaması","y":["Yunan filozoflarının mitolojiyi mantıktan üstün tutan bir yöntem izlemesi","Yazı kültürünün dinî konuların kaydedilmesine ve aktarılmasına elverişli olmaması","Felsefenin dinî konulara girmesini engelleyen kamusal bir düzenin bulunması"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Tarihsel bağlam","z":"orta","b":"Anlama"},{"s":"Bir dinin Tanrı’nın insana kendini bildirdiği iddiasıyla yayılması, felsefeyi hangi tür sorularla yüzleştirir?","d":"Vahyin imkânı ve Tanrı’nın bilinebilirliği gibi sorularla","y":["Geometrik ispat yöntemlerinin nasıl geliştirileceği sorusuyla","Evrenin matematiksel olarak nasıl ölçüleceği sorusuyla","Siyasal iktidarın meşruiyetinin nasıl sağlanacağı sorusuyla"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Tarihsel bağlam","z":"orta","b":"Anlama"},{"s":"Farabî ile Aquino’lu Thomas’ı ortak bir başlık altında anmamızın nedeni nedir?","d":"İkisi de din ile felsefe arasındaki ilişkiyi sistemli biçimde işlemiştir","y":["İkisi de mantıkçı pozitivist akımın öncüleri arasında sayılır","İkisi de dinî tecrübeyi psikolojik yöntemle inceleyen ilk araştırmacılardır","İkisi de “din felsefesi” terimini ilk kullanan düşünürler arasındadır"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Tarihsel bağlam","z":"kolay","b":"Hatırlama"},{"s":"Din felsefesinin bir disiplin olarak gelişebilmesi için hangi iki birikimin belli bir olgunluğa ulaşması gerekir?","d":"Dinî düşünce ile felsefî çaba","y":["Hukuk düşüncesi ile siyaset düşüncesi","Deneysel bilim ile teknoloji","Edebiyat ile güzel sanatlar"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Tarihsel bağlam","z":"kolay","b":"Anlama"},{"s":"Bir araştırmacı Tanrı’nın varlığı tartışmasında tarihî, ilmî ve mantıkî bütün verileri hesaba katıyor. Hangi ölçüte uymaktadır?","d":"Şümullülük","y":["Rasyonellik","Tutarlılık","Objektiflik"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Felsefî bakış tarzı","z":"kolay","b":"Uygulama"},{"s":"Bir düşünür savunduğu iki tezin birbirini dışladığını fark edip birini gözden geçiriyor. Bu davranış hangi ölçütle ilgilidir?","d":"Tutarlılık","y":["Şümullülük","Rasyonellik","Objektiflik"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Felsefî bakış tarzı","z":"kolay","b":"Uygulama"},{"s":"Bir yazar önceden benimsediği inancı haklı çıkarmak için işine gelen verileri seçip gerisini görmezden geliyor. Hangi ölçüt çiğnenmiştir?","d":"Objektiflik","y":["Şümullülük","Tutarlılık","Rasyonellik"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Felsefî bakış tarzı","z":"orta","b":"Uygulama"},{"s":"Ruhun ölümsüzlüğünü vahye başvurmadan aklî argümanlarla temellendirmeye çalışmak hangi ölçütün tipik örneğidir?","d":"Rasyonellik","y":["Objektiflik","Tutarlılık","Şümullülük"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Felsefî bakış tarzı","z":"kolay","b":"Uygulama"},{"s":"Din felsefesi çalışan biri için hangisi sağlıklı bir başlangıç tutumudur?","d":"Dinin doğruluğu konusunda kararı araştırmadan önce vermemek","y":["Savunacağı sonucu önce belirleyip delilleri ona göre toplamak","Dinî metinlerin söylediklerini sorgulamadan sistemleştirmek","Dinî tecrübeyi bilimsel olmadığı gerekçesiyle dışarıda bırakmak"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Felsefî bakış tarzı","z":"orta","b":"Değerlendirme"},{"s":"Dinin evrensel ve tek bir tanımını yapmanın zor olmasının temel nedeni hangisidir?","d":"Çok sayıda dinin bulunması ve her birinin başka unsurlara ağırlık vermesi","y":["Dil bilgisinin “din” gibi soyut bir kavramı ifade etmeye elverişli olmaması","Dinin tarihte çok yeni ortaya çıkmış, henüz yeterince tartışılmamış bir olgu olması","Dinin tanımının deneysel bilimlerin ilgi alanına girdiğinin düşünülmesi"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Dinin mahiyeti","z":"orta","b":"Anlama"},{"s":"Bir dinde ayinlerin nasıl yapılacağını belirleyen kurallar dinin hangi boyutuna girer?","d":"İbadî boyut","y":["Bilgisel boyut","Ahlâkî boyut","Tarihsel boyut"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Dinin mahiyeti","z":"kolay","b":"Uygulama"},{"s":"Bir din kitabından alınan şu üç parça sırasıyla hangi boyutlara örnektir: (i) Allah’ın sıfatları, (ii) namaz kılma biçimi, (iii) dürüstlük ilkesi?","d":"Bilgisel, ibadî, ahlâkî","y":["İbadî, bilgisel, ahlâkî","Ahlâkî, ibadî, bilgisel","Bilgisel, ahlâkî, ibadî"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Dinin mahiyeti","z":"orta","b":"Uygulama"},{"s":"Kitaplı dinler açısından din için hangisi söylenebilir?","d":"Hem bireysel hem toplumsal yanı olan, sistemleşmiş bir kurumdur","y":["Bireyin iç dünyasıyla sınırlı kalan, kurumsal karşılığı bulunmayan bir sezgidir","Kutsal bir varlığa bağlanmadan yürütülen ahlâkî bir yaşam planıdır","Dönemin siyasal ihtiyaçlarına göre değişen bir gelenekler toplamıdır"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Dinin mahiyeti","z":"orta","b":"Anlama"},{"s":"Gazâlî’nin vurgusuna göre din en çok neye benzer?","d":"Yaşanarak bilinen ruhânî bir zevk ve tecrübeye","y":["Akıl yürütmeyle ulaşılan sonuçlar bütününe","Gözleme dayalı bir olgular derlemesine","Mantıksal önermelerden kurulu kapalı bir sisteme"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Din ve felsefe farkı","z":"kolay","b":"Hatırlama"},{"s":"Felsefe ile din arasındaki farkı en iyi hangi karşılaştırma yansıtır?","d":"Felsefe düşünüp akıl yürütmeyi, din yaşayıp tecrübe etmeyi esas alır","y":["Felsefe duyguya dayanan, din ise akıl yürütmeye dayanan bir faaliyettir","Felsefe toplumsal bir olgudur, din ise bireysel bir olgudur ve ikisi bağımsızdır","İkisi de aynı yöntemle ve aynı amaçla yürütülen faaliyetlerdir"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Din ve felsefe farkı","z":"orta","b":"Anlama"},{"s":"“Kur’ân hikmetlerle doludur ama bir felsefe kitabı değildir” sözü neyi gösterir?","d":"Bir metnin hikmet içermesinin onu felsefî bir sisteme dönüştürmediğini","y":["Felsefenin kaynağının dinî metinler olduğunu ve felsefenin bu metinlerden türetildiğini","Dinî metinlerin akıl dışı olduğunu ve felsefî tartışmaya kapalı kaldığını","Felsefî düşüncenin din için zararlı olduğunu ve ondan uzak durulması gerektiğini"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Din ve felsefe farkı","z":"orta","b":"Analiz"},{"s":"Bir araştırmacı evrenin düzenine ilişkin bilimsel verilerden hareketle Tanrı’nın varlığını temellendirmeye çalışıyor. Hangi yaklaşımı izlemektedir?","d":"Dinî olmayan verilerden dinî hükmü temellendirme yaklaşımını","y":["Dinî tecrübenin yapısını içeriden ve doğrudan çözümleme yaklaşımını","Dinî hükmü şüphenin ötesinde kabul eden yaklaşımı","Dinin toplumsal işlevini betimleyip ölçmeye çalışan yaklaşımı"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Din ve felsefe farkı","z":"orta","b":"Uygulama"},{"s":"Bir düşünür bir mistiğin yaşadığı deneyimi dışarıdan veri aramadan, doğrudan o deneyimin yapısı üzerinden çözümlüyor. Bu çalışma hangi yaklaşıma uyar?","d":"Din fenomeninden yola çıkıp temel hükümleri açıklama yaklaşımına","y":["Dinî olmayan verilerle dinî hükmü kanıtlamaya çalışan yaklaşıma","Dinin toplumsal fonksiyonlarını sayıp sınıflandıran yaklaşıma","Din dilini mantıksal anlamlılık ölçütüyle sınayan yaklaşıma"],"t":20,"p":"1. hafta: Zapoot (yeni, 20 soru)","k":"Din ve felsefe farkı","z":"zor","b":"Uygulama"},{"s":"Bir öğrenci “Hegel’den önce kimse din felsefesi yapmamıştır” diyor. Bu görüşe karşı en güçlü itiraz hangisidir?","d":"İsim sonradan konsa da Farabî ve Aquino’lu Thomas gibi düşünürler din ile felsefe ilişkisini işlemiştir; konu adından önce vardır","y":["Hegel’in eseri din felsefesiyle ilgili değildir, olsa olsa tarih felsefesi içinde değerlendirilebilir; bu yüzden tarih yanlış hesaplanmıştır","Din felsefesi ancak dinî otoritenin zayıfladığı toplumlarda yapılabilir; bu yüzden Hegel’den önceki dönem kapsam dışındadır","Terimlerin tarihi bilimsel açıdan önemsizdir; bu yüzden bir disiplinin ne zaman başladığı sorusu anlamlı değildir"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Terimin kökeni","z":"orta","b":"Değerlendirme"},{"s":"Felsefenin Antik Yunan’da gelişmesi, din felsefesinin ise vahiy dinleriyle birlikte olgunlaşması birlikte düşünüldüğünde hangi sonuç en tutarlıdır?","d":"Din felsefesi, felsefî birikim ile ciddi felsefî problemler doğuran dinî düşüncenin buluşmasıyla ortaya çıkar","y":["Felsefe geliştikçe dinin toplumdaki yeri zayıflar; bu yüzden din felsefesi ancak geç dönemlerde ortaya çıkabilmiştir","Din felsefesi, felsefî birikimin belli bir düzeye ulaşmasıyla başka bir koşul gerekmeden kendiliğinden ortaya çıkar","Vahiy dinleri felsefî düşünceyi ortadan kaldırdığı için din felsefesi sıfırdan kurulan yeni bir uğraş olmuştur"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Tarihsel bağlam","z":"zor","b":"Analiz"},{"s":"Bir tezin lehindeki ve aleyhindeki bütün delillerin tarihî, ilmî ve mantıkî açıdan birlikte tartılması felsefî bakış tarzının hangi özelliğinin gereğidir ve neden?","d":"Şümullülük; çünkü konuya bakılabilecek bütün açıların hesaba katılması gerekir","y":["Rasyonellik; çünkü akıl yürütme tek başına bütün verilerin yerini tutar","Objektiflik; çünkü sonucun önceden belirlenmesi delillerin sayısıyla ilgilidir","Tutarlılık; çünkü delil sayısı arttıkça çelişkiler kendiliğinden ortadan kalkar"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Felsefî bakış tarzı","z":"orta","b":"Analiz"},{"s":"Bir yazar Tanrı’nın varlığı için aklî deliller sunuyor, ancak sonucun “vardır” olacağını baştan kabul edip işine yarayan delilleri seçiyor. Bu yazar hakkında hangisi söylenebilir?","d":"Rasyonellik özelliğini taşıyor, fakat objektiflik ve şümullülük ölçütlerini karşılamıyor","y":["Dört özelliğin hepsini taşıyor, çünkü aklî delil kullanmak yeterli ve belirleyici bir ölçüttür","Şümullülüğü taşıyor, fakat aklî delil kullanmadığı için rasyonellikten uzaktır","Objektifliği taşıyor, çünkü inanç sahibi olmak delil sunmaya engel değildir"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Felsefî bakış tarzı","z":"zor","b":"Değerlendirme"},{"s":"Bir düşünür hem “bütün bilgiler deneyle doğrulanmalıdır” diyor hem de “Tanrı’nın varlığı deneyle doğrulanamaz ama doğrudur” diyor. Felsefî bakış tarzına göre ne yapılmalıdır?","d":"İki önerme arasındaki çelişki tespit edilip giderilmelidir; bu, tutarlılık ölçütünün gereğidir","y":["İkinci önerme dinî olduğu için sorgulanmamalıdır; bu, objektifliğin gereğidir","Birinci önerme bilimsel olduğu için ikincisi dışarıda bırakılmalıdır; bu, şümullülüğün gereğidir","Çelişki önemsenmemelidir; çünkü din ile felsefe birbirinden ayrı alanlardır"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Felsefî bakış tarzı","z":"orta","b":"Uygulama"},{"s":"Bir araştırmacı dini ibadet uygulamaları üzerinden tanımlıyor. Bilgisel, ibadî ve ahlâkî boyutlara göre bu tanımın en önemli eksiği nedir?","d":"İnanç doktrinlerini ve ahlâkî değerler sistemini dışarıda bırakması","y":["İbadet uygulamalarının ayrıntılarını yeterince vermemesi ve örnek göstermemesi","Dinin tarihsel gelişim sürecini ve kaynaklarını hesaba katmaması","Dinin toplumsal işlevlerine gereğinden fazla yer verip bireyi unutması"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Dinin mahiyeti","z":"orta","b":"Analiz"},{"s":"Kitaplı dinler perspektifine göre bir din tanımlanırken hangi özellikler bir arada aranır?","d":"Ferdî ve içtimaî yan, sistemleşmiş fikir ve uygulama, bir yaşama tarzı ve müteâl bir Yaratıcıya bağlanma","y":["Siyasal otoriteye bağlılık, hukukî yaptırımlar ve devlet eliyle düzenlenen bir ibadet takvimi ile ceza sistemi","Bireyin gizli kalan sezgileri, kurumsal bir yapıdan bağımsız duygular ve kişisel bir ahlâk anlayışı","Ortak bir ritüeller dizisi, bayramlar ve toplumsal dayanışmayı güçlendiren, herkesin katıldığı törenler"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Dinin mahiyeti","z":"orta","b":"Anlama"},{"s":"Bir öğrenci “dini akıl yürüterek tam olarak anlayabiliriz” diyor. Din ile felsefe arasındaki ayrım bu görüşü nasıl sınırlar?","d":"Dinin özünde yaşanan tecrübe ve ruhânî zevk, felsefenin özünde ise düşünmek bulunduğunu hatırlatarak","y":["Dinin aklî olmadığını göstererek, felsefenin din konusunda söz söyleyemeyeceğini ortaya koyarak","Felsefenin dinden daha değerli bir bilgi türü olduğunu kanıtlayarak ve dini onun içine yerleştirerek","Dinî metinlerin felsefî sistemlere dönüştürülmesi gerektiğini savunarak ve böylece sınırı kaldırarak"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Din ve felsefe farkı","z":"zor","b":"Değerlendirme"},{"s":"Bir araştırmacı Tanrı’nın varlığını fizik verileriyle tartışıyor; tarihî ve mantıkî verilere hiç yer vermiyor. Felsefî bakış tarzına göre hangi özellik eksiktir?","d":"Şümullülük","y":["Objektiflik","Rasyonellik","Tutarlılık"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Felsefî bakış tarzı","z":"orta","b":"Uygulama"},{"s":"Birisi “din felsefesi yapan kişi dinsizdir” diyor. Objektiflik özelliği bu görüşe nasıl cevap verir?","d":"Din felsefecisi peşin hüküm vermez; inançlı ya da inançsız olması, verileri zorlamadığı sürece araştırmanın niteliğini belirlemez","y":["Din felsefecisinin dine karşı olması gerekir; çünkü tarafsızlık ancak dinî bağlılığın bulunmamasıyla sağlanabilir ve korunabilir","Din felsefecisi inançlı olamaz; çünkü inanç, hangi veriden hareket edilirse edilsin araştırmayı baştan engeller ve yönlendirir","Din felsefecisi dinî hükümleri araştırmadan önce kabul etmek zorundadır; çünkü aksi hâlde konuyu doğru tanıyamaz ve değerlendiremez"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Felsefî bakış tarzı","z":"zor","b":"Değerlendirme"},{"s":"Farabî ile Aquino’lu Thomas farklı çağlarda ve farklı dinlerde yetişmiştir. İkisinin de aynı konuları tartışması neyi gösterir?","d":"Din-felsefe ilişkisinin vahiy dinlerinin doğurduğu ortak bir problem alanı olduğunu","y":["Din felsefesinin Orta Çağ’a özgü kalmış, sonraki dönemlerde sürmeyen bir uğraş olduğunu","Felsefenin dinî inançtan ayrılarak gelişemeyeceğini ve ona bağımlı kaldığını","Farklı dinlerin aynı doktrinleri paylaştığını ve aynı kaynaktan doğduğunu"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Tarihsel bağlam","z":"orta","b":"Analiz"},{"s":"Bir din felsefecisi, evrene ilişkin bilimsel verilerden Tanrı’nın varlığına giden bir çalışmayı inceliyor. Bu çalışma iki yaklaşımdan hangisine girer ve diğerinden farkı nedir?","d":"Birinci yaklaşıma girer; ikinci yaklaşım din fenomeninden yola çıkıp dinî tecrübenin kendisini çözümler","y":["İkinci yaklaşıma girer; birinci yaklaşım dinî tecrübeyi içeriden çözümleyen yaklaşımdır","Her iki yaklaşıma da girer; çünkü bilimsel veriler ile dinî tecrübe birbirinden ayrılamaz ve aynı kaynaktan beslenir","Birinci yaklaşıma girer; ikinci yaklaşım dinî hükümleri şüphenin ötesinde kabul eden yaklaşımdır"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Din ve felsefe farkı","z":"zor","b":"Analiz"},{"s":"Aşağıdaki araştırma planlarından hangisi felsefî bakış tarzının dört özelliğini en iyi birlikte yansıtır?","d":"Vahyin imkânını aklî argümanlarla, tarihî ve ilmî verilerle birlikte ele alıp çelişkileri ayıklayarak, sonuca önceden karar vermeden değerlendirmek","y":["Vahyin imkânını tarihî belgelere dayanarak ele alıp sonucu baştan belirleyerek, çelişkileri ve karşıt görüşleri dikkate almadan değerlendirmek","Vahyin imkânını mantıkî tutarlılık açısından tartışıp tarihî ve ilmî verileri kapsam dışında bırakarak ve sonucu kesin saymadan değerlendirmek","Vahyin imkânını inanç sahiplerinin ortak görüşüne dayanarak onaylayıp farklı görüşleri ve karşıt delilleri hesaba katmadan değerlendirmek"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Felsefî bakış tarzı","z":"zor","b":"Değerlendirme"},{"s":"Farklı dinlerden iki araştırmacı ortak bir din tanımı üzerinde çalışıyor. Kitaplı dinler perspektifinden hangi unsur ortak tanımın dayanağı olabilir?","d":"Müteâl ve kutsal bir Yaratıcıya bağlanma ve bunun fikir ve uygulamada sistemleşmesi","y":["Aynı ibadet biçimlerinin bütün dinlerde bulunması ve aynı sırayla uygulanması","Aynı doktrinlerin bütün dinlerce paylaşılması ve aynı terimlerle ifade edilmesi ve öğretilmesi","Bütün dinlerin aynı tarihsel dönemde ortaya çıkmış olması ve birbirini etkilemesi"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Dinin mahiyeti","z":"zor","b":"Analiz"},{"s":"“Akıl yürütmek felsefenin, duymak ve yaşamak dinin işidir” görüşünü benimseyen biri için din felsefesi nasıl bir uğraştır?","d":"Dinî yaşantıyı akıl yürütmenin konusu yapan, ancak dinin yerini almayan bir uğraş","y":["Din yaşantısının kendisini ortadan kaldırmayı ve yerini almayı amaçlayan bir uğraş","Dinî yaşantıyı felsefî tecrübeyle özdeşleştiren, ikisi arasındaki farkı silen bir uğraş","Felsefenin dinî öğretilere dönüştürüldüğü ve dinin akla bağlandığı bir uğraş"],"t":60,"p":"1. hafta: Quiz (yeni, 15 soru)","k":"Din ve felsefe farkı","z":"zor","b":"Analiz"},{"s":"Bir araştırmacı Tanrı’nın varlığına ilişkin aklî delilleri inceliyor. Çalışması hangi problem kategorisindedir?","d":"Metafizik ve kozmolojik problemler","y":["Epistemolojik ve bilgi kuramsal problemler","Dinî sembolizm ve sembol çözümlemesi","Dil ve mantık çözümlemesi problemleri"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Ana problemler","z":"kolay","b":"Uygulama"},{"s":"Vahyin ve dinî tecrübenin bilgi kaynağı olarak değeri tartışılıyor. Bu tartışma hangi kategoriye girer?","d":"Epistemolojik ve bilgi kuramsal problemler","y":["Dinî sembolizm ve sembol çözümlemesi","İlişkisel ve disiplinler arası problemler","Metafizik ve kozmolojik problemler"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Ana problemler","z":"orta","b":"Uygulama"},{"s":"“Tanrı vardır” gibi bir cümlenin mantıkî olarak anlamlı sayılıp sayılmayacağı sorusu hangi alana girer?","d":"Dil ve mantık çözümlemesi problemleri","y":["Metafizik ve kozmolojik problemler","İlişkisel ve disiplinler arası problemler","Dinî sembolizm ve sembol çözümlemesi"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Ana problemler","z":"orta","b":"Uygulama"},{"s":"Dinin ahlâkla ve sanatla ilişkisini inceleyen bir çalışma hangi kategoriye girer?","d":"İlişkisel ve disiplinler arası problemler","y":["Epistemolojik ve bilgi kuramsal problemler","Metafizik ve kozmolojik problemler","Dil ve mantık çözümlemesi problemleri"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Ana problemler","z":"kolay","b":"Uygulama"},{"s":"Bir ibadet mekânında kullanılan nesnelerin neyi temsil ettiğini inceleyen çalışma hangi kategoriye girer?","d":"Dinî sembolizm ve sembol çözümlemesi","y":["İlişkisel ve disiplinler arası problemler","Dil ve mantık çözümlemesi problemleri","Epistemolojik ve bilgi kuramsal problemler"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Ana problemler","z":"kolay","b":"Uygulama"},{"s":"İnanma, bilme, şüphe, zan ve yakîn kavramlarını çözümleyen bir çalışma hangi kategoridedir?","d":"Epistemolojik ve bilgi kuramsal problemler","y":["Metafizik ve kozmolojik problemler","Dinî sembolizm ve sembol çözümlemesi","İlişkisel ve disiplinler arası problemler"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Ana problemler","z":"orta","b":"Uygulama"},{"s":"Ölümden sonra hayat ve ruhun ölümsüzlüğü sorunları hangi kategoriye girer?","d":"Metafizik ve kozmolojik problemler","y":["Dil ve mantık çözümlemesi problemleri","Epistemolojik ve bilgi kuramsal problemler","Dinî sembolizm ve sembol çözümlemesi"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Ana problemler","z":"kolay","b":"Hatırlama"},{"s":"Bir filozofun din felsefesi yapabilmesi için beş problem kategorisinin hepsiyle uğraşması gerekir mi?","d":"Gerekmez; her filozof kendi felsefî tutumuna göre bazı problemlere ağırlık verir","y":["Gerekir; aksi hâlde çalışması din felsefesi sayılmaz ve eksik kalır","Gerekir; ancak ilişkisel problemler dışarıda bırakılabilir ve çalışma yine geçerli olur","Gerekmez; çünkü din felsefesinde problem kategorisi diye bir ayrım yoktur"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Ana problemler","z":"orta","b":"Anlama"},{"s":"Descartes, Leibniz ve Spinoza din felsefesinde en çok hangi konuya ağırlık vermiştir?","d":"Tanrı’nın varlığının aklî delillerle kanıtlanmasına ve ontolojik delile","y":["Din dilinin mantıkî çözümlenmesine ve anlamlılık ölçütüyle sınanmasına","Dinî tecrübenin psikolojik boyutuna ve mistik yaşantının incelenmesine","Dinin toplumsal işlevlerine ve kurumsal yapısının çözümlenmesine"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Felsefî yaklaşımlar","z":"orta","b":"Hatırlama"},{"s":"Mantıkçı pozitivistler ve dil çözümlemecileri din felsefesinde en çok neyle ilgilenmiştir?","d":"Din dilinin dil ve mantık açısından çözümlenip eleştirilmesiyle","y":["Dinî sembollerin tarihî gelişimiyle ve kültürler arası yayılımıyla","Âlemin yaratılışının kozmolojik ayrıntılarıyla ve evrenin başlangıcıyla","Dinî tecrübenin varoluşsal boyutuyla ve insanın kaygılarıyla"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Felsefî yaklaşımlar","z":"orta","b":"Hatırlama"},{"s":"Dinî tecrübeyi merkeze alan ve âlemden Tanrı’ya gitmeyi hedefleyen akıl yürütmelere önem veren filozoflar hangi gruba girer?","d":"Tecrübeci filozoflar","y":["Analitik filozoflar","Varoluşçu filozoflar","Akılcı filozoflar"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Felsefî yaklaşımlar","z":"orta","b":"Hatırlama"},{"s":"Varoluşçu ve fenomenolojik düşünürler din felsefesinde en çok hangi yönü işlemiştir?","d":"Dinî tecrübenin varoluşsal boyutunu","y":["Tanrı’nın varlığının matematiksel ispatını","Dinî sembollerin tarihsel kökenini","Dinî hükümlerin mantıksal tutarlılığını"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Felsefî yaklaşımlar","z":"orta","b":"Hatırlama"},{"s":"Kelâmcı ile din felsefecisini ayıran temel hareket noktası hangisidir?","d":"Kelâmcı tasdikle, yani inançla yola çıkar; din felsefecisi hükümleri inceleme dışında bırakmaz","y":["Kelâmcı nakle, din felsefecisi akla başvurur; ikisi aynı hükümleri aynı gerekçelerle savunur","Kelâmcı din bilimlerine, din felsefecisi tarihe başvurur; ikisi de dinî hükmü şüphenin ötesinde sayar","Kelâmcı dinî tecrübeyi, din felsefecisi ibadeti inceler; ikisi de dışarıdan bir bakış açısı benimser"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Din felsefesi ve kelâm","z":"orta","b":"Anlama"},{"s":"Kelâm ile karşılaştırıldığında din felsefesi dine nasıl yaklaşır?","d":"Uzaktan ve dışarıdan, hürriyet içinde, objektif ve eleştirel biçimde","y":["İçeriden ve inançlı bir savunma duruşuyla, hükümleri sistemleştirerek","Dinî otoritelerin yorumlarına bağlı kalarak ve şüpheyi dışarıda bırakarak","Dinî hükümleri şüphenin ötesinde sayıp onları öğretmeyi amaçlayarak"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Din felsefesi ve kelâm","z":"orta","b":"Anlama"},{"s":"Din felsefesine “felsefî kelâm” ya da “lâik kelâm” diyenler hangi benzerliğe dikkat çekmektedir?","d":"İkisinin de dinî konuları aklî yolla ele alması","y":["İkisinin de aynı inançlı duruşla yola çıkması","İkisinin de dinî hükümleri sorgulamaması ve savunması","İkisinin de aynı delilleri kullanması"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Din felsefesi ve kelâm","z":"zor","b":"Analiz"},{"s":"Din felsefesinin en çok yararlandığı din bilimi hangisidir ve neden?","d":"Dinler tarihi; çünkü filozofun düşünebilmesi için tarihçinin sunduğu malzeme gerekir","y":["Din sosyolojisi; çünkü dinî inancı toplumun içinden ve toplumsal bağlamıyla inceler","Din psikolojisi; çünkü dinî inancın duygusal yönünü ve birey üzerindeki etkisini ölçer","Din antropolojisi; çünkü kültürleri karşılaştırıp sınıflandırmayı amaçlar"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Din bilimleri","z":"orta","b":"Anlama"},{"s":"Dinî şuurun oluşumunu ve mistik yaşantıyı inceleyen din bilimi hangisidir?","d":"Din psikolojisi","y":["Din sosyolojisi","Dinler tarihi","Din antropolojisi"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Din bilimleri","z":"kolay","b":"Hatırlama"},{"s":"Farklı toplumlardaki dinî pratiklerin kültürel boyutlarını karşılaştıran çalışma hangi alana girer?","d":"Din antropolojisi","y":["Din psikolojisi","Din sosyolojisi","Dinler tarihi"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Din bilimleri","z":"orta","b":"Uygulama"},{"s":"Bir din psikolojisi çalışmasının sonuçları değerlendirilirken filozof ne yapar?","d":"Yöntem, kuram ve açıklamaları tahlil ve tenkit ederek o alana açıklık getirir","y":["Sonuçları aynen benimser ve bunları dinin hakikatinin kanıtı sayar","Çalışmayı yok sayıp kendi akıl yürütmesine dayanır","Çalışmayı dinî otoritelere sunup onların kararını bekler"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Din bilimleri","z":"orta","b":"Değerlendirme"},{"s":"Ontolojik delili değerlendiren bir din filozofu için en öncelikli ölçüt hangisidir?","d":"Delilin iddiasının doğruluğu","y":["Delilin kimin tarafından ileri sürüldüğü","Delilin hangi çağda ortaya çıktığı","Delilin kaç kişi tarafından kabul edildiği"],"t":20,"p":"2. hafta: Zapoot (yeni, 20 soru)","k":"Din bilimleri","z":"orta","b":"Değerlendirme"},{"s":"Bir araştırmacı din dilinin mantıkî statüsünü incelemekte, Tanrı’nın varlığı ya da dinin toplumsal işlevleri üzerine çalışmamaktadır. Derste verilen “önemli not”a göre bu durum nasıl değerlendirilir?","d":"Çalışma din felsefesidir; her filozof felsefî tutumuna göre bazı problemlere ağırlık verir, hepsiyle uğraşmak zorunda değildir","y":["Çalışma din felsefesi sayılmaz; çünkü din felsefesi sayılmak için beş problem kategorisinin hepsiyle uğraşmak gerekir","Çalışma dil bilimine aittir; çünkü din dilini inceleyen çalışmalar din felsefesinin konusu sayılmaz ve ona bağlanamaz","Çalışma ancak kelâm ile birlikte yürütülürse din felsefesi sayılır; tek başına yürütüldüğünde herhangi bir felsefî anlam taşımaz"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Ana problemler","z":"orta","b":"Değerlendirme"},{"s":"Âlemdeki düzenden hareketle Tanrı’ya ulaşma çabasının bilgi olarak değerini sorgulayan bir çalışma hangi problem alanında ağırlık taşır ve neden?","d":"Epistemolojik problemler; çünkü âlemle ilgili bilgilerden Tanrı’nın bilinmesine gitme çabasının değeri sorgulanmaktadır","y":["Metafizik ve kozmolojik problemler; çünkü çalışma âlemin yaratılışını ve Tanrı’nın varlığını konu almaktadır","Sembolizm; çünkü âlemdeki düzen dinî bir simge olarak ele alınmakta ve anlamı çözümlenmektedir","İlişkisel problemler; çünkü din ile bilim arasındaki ilişki ve ortak sınırlar incelenmektedir"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Ana problemler","z":"zor","b":"Analiz"},{"s":"Bir filozof “Tanrı vardır” cümlesinin doğrulanıp doğrulanamayacağını ve anlamlı olup olmadığını sorguluyor. Bu filozof hangi akıma ve hangi problem alanına yakındır?","d":"Analitik filozoflara ve dil ve mantık analizine","y":["Akılcı filozoflara ve metafizik ve kozmolojik problemlere","Varoluşçu filozoflara ve ilişkisel problemlere","Tecrübeci filozoflara ve sembolizme"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Felsefî yaklaşımlar","z":"zor","b":"Analiz"},{"s":"Akılcı filozoflar ile tecrübeci filozofların din felsefesindeki öncelikleri nasıl ayrışır?","d":"Akılcılar Tanrı’nın varlığına dair aklî delillere, tecrübeciler dinî tecrübeye ve âlemden Tanrı’ya gidişe ağırlık verir","y":["Akılcılar dinî tecrübeyi ve mistik yaşantıyı, tecrübeciler ise ontolojik delili öne çıkarır","Akılcılar din dilinin çözümlenmesine, tecrübeciler varoluşçu çözümlemelere ağırlık verir","İkisinin öncelikleri aynıdır; aralarındaki fark, adlandırmadan ve kullanılan terimlerden ibarettir"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Felsefî yaklaşımlar","z":"zor","b":"Analiz"},{"s":"Bir kelâmcı ile bir din felsefecisi ahiret konusunu tartışıyor. Kelâmcı delilleri sıralayıp hükmü savunurken din felsefecisi hükmün temellendirilmesini eleştirel biçimde sorguluyor. Aralarındaki temel fark nedir?","d":"Kelâmcı dinî hükmü şüphenin ötesinde kabul ederek yola çıkar; din felsefecisi hükümleri inceleme dışında bırakmaz","y":["Kelâmcı akla başvurur, din felsefecisi vahye başvurur; bu yüzden iki disiplin birbirinden bağımsızdır","Kelâmcı dinî tecrübeyi kabul etmez, din felsefecisi onu kabul eder; bu yüzden sonuçları farklıdır","Kelâmcı tarihsel yöntem, din felsefecisi deneysel yöntem kullanır; bu yüzden konuları ayrışır"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Din felsefesi ve kelâm","z":"orta","b":"Analiz"},{"s":"Aşağıdakilerden hangisi bir çalışmanın kelâma değil din felsefesine ait olduğunu en iyi gösterir?","d":"Dinî hükmü şüphenin ötesinde görmeyip hür bir araştırmanın konusu yapması","y":["Dinî hükmü aklî ve naklî delillerle birlikte savunması ve açıklaması","Dinî hükmü sistemleştirip tutarlı bir bütün hâline getirmesi ve öğretmesi","Dinî hükmü inançla kabul edip hayatî bir mesele olarak ele alıp sürdürmesi"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Din felsefesi ve kelâm","z":"orta","b":"Değerlendirme"},{"s":"Bir dinler tarihçisi bir ritüelin tarihsel gelişimini tasvir ediyor; bir filozof ise o ritüelin dayandığı inancın doğruluk iddiasını değerlendiriyor. Bu iki çalışma arasındaki rol ayrımı nedir?","d":"Tarihçi olguları tasvir ve açıklar; filozof doğruluk ve değer sorusunu ele alır","y":["Tarihçi doğruluk iddiasını değerlendirir; filozof olguları tasvir edip kayda geçirir","İkisi de aynı soruyu sorar, kullandıkları yöntemler birbirinden farklıdır","Filozof tarihsel veriyi kullanmaz; tarihçi ise felsefî soruları kesin olarak reddeder"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Din bilimleri","z":"zor","b":"Analiz"},{"s":"Bir din sosyoloğu “din toplumsal bütünleşmeye hizmet ettiğine göre doğrudur” sonucuna varıyor. Derste verilen ilkelere göre bu çıkarımın sorunu nedir?","d":"Din bilimleri tasvir ve açıklamayla yetinir; dinin hakikati ve değeri onların işi değildir, hakikat işlevden ayrı düşünülür","y":["Toplumsal işlevler araştırma konusu yapılmamalıdır; çünkü bu, dinin kutsallığına zarar verir ve inancı sarsar","Din sosyolojisi felsefeden bağımsız olduğu için sonuç çıkaramaz; veri toplayıp sınıflandırabilir","Din ancak psikolojik yöntemle incelenebilir; toplumsal işlevleri ise ölçülemez ve bu yüzden bilimsel değildir"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Din bilimleri","z":"zor","b":"Değerlendirme"},{"s":"Birisi “bu inanç psikolojik bir ihtiyaçtan doğmuştur, o hâlde yanlıştır” diyor. Filozofun değer ve hakikat sorusunu menşe ve işlevden ayırmasına göre bu çıkarım için ne söylenebilir?","d":"Geçerli değildir; bir inancın nasıl ortaya çıktığı, doğru olup olmadığını tek başına belirlemez","y":["Doğrudur; çünkü psikolojik kökene dayanan her inanç yanlış sayılmak zorundadır ve sorgulanamaz","Yanlıştır; çünkü inançlar psikolojik bir ihtiyaçtan değil, akıl yürütmeden doğar","Kanıtlanamaz; çünkü psikoloji dinî konuların dışında kalan ve bu konuda söz hakkı olmayan bir bilimdir"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Din bilimleri","z":"zor","b":"Değerlendirme"},{"s":"İbn Sînâ, Anselm ve Descartes’ın ontolojik delille ilgili iddiaları bir derste inceleniyor. Din felsefecisinin tutumuna göre öğrencinin öncelikle neyi sorgulaması gerekir?","d":"Delilin iddiasının doğru olup olmadığını; kimin ileri sürdüğü ikinci derecede önem taşır","y":["Delilin hangi düşünür tarafından ileri sürüldüğünü; çünkü delilin değeri sahibinin otoritesine bağlıdır","Delilin hangi dinî gelenekte doğduğunu; çünkü doğruluk ancak geleneğin içinden belirlenebilir","Delilin kaç yüzyıl önce yazıldığını; çünkü eski deliller daha güvenilir ve sınanmış sayılır"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Din bilimleri","z":"orta","b":"Uygulama"},{"s":"Bir ilahiyatçı ile bir sosyolog din konusunda ortak bir dil kurmaya çalışıyor. Filozofun bütünleştirici rolü bu durumda nasıl işler?","d":"İlahiyatla sosyal bilimler arasında bağlantı noktaları kurar ve bilgide bütünlük sağlamaya çalışır","y":["Sosyoloğun bulgularını geçersiz sayarak ilahiyatçının görüşlerini öne çıkarır ve tartışmayı kapatır","İlahiyatçının görüşlerini sosyal bilim bulgularına indirgeyerek ortak bir dil kurduğunu varsayar","İki alandan da uzak durup kendi alanının sınırlarını korumaya ve genişletmeye çalışır"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Din bilimleri","z":"orta","b":"Anlama"},{"s":"Kriz dönemlerinde insanların dinî inancının nasıl pekiştiğini ve bunun bireylerde nasıl bir ruhsal rahatlama sağladığını inceleyen bir çalışma hangi alana girer?","d":"Din psikolojisine; çünkü dinî yaşantının bireydeki ruhsal yönü incelenmektedir","y":["Din sosyolojisine; çünkü dinî inançla ilgili toplumsal bir olgu ele alınmaktadır","Dinler tarihine; çünkü geçmişteki olayların anlatılması esas alınmaktadır","Din antropolojisine; çünkü farklı kültürler arasında karşılaştırma yapılmaktadır"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Din bilimleri","z":"orta","b":"Uygulama"},{"s":"Bir filozof, bilimsel olarak kanıtlanmış sonuçlarla ideolojik girdileri birbirinden ayırıyor; dinin öğrettikleri ile bilimin bulgularını karşılaştırarak bilgide bütünlük kurmaya çalışıyor. Bu çalışma filozofun hangi rolüne örnektir?","d":"Din bilimlerini tahlil ve tenkit edip o alanlara açıklık getirme ve bilgide bütünlük sağlama rolüne","y":["Dinî hükümleri savunma ve onları delillerle temellendirme rolüne ve bunun kurumsallaşmasına","Dini toplumsal bir kurum olarak betimleme ve işlevlerini sayıp sınıflandırma rolüne","Dinler tarihinin malzemesini toplayıp arşivleme ve bunları dönemlere ayırma rolüne"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Din bilimleri","z":"zor","b":"Değerlendirme"},{"s":"Bir öğrenci felsefî yaklaşımlar konusunu özetlerken şu eşleştirmeleri yapıyor. Hangisi doğrudur?","d":"Varoluşçu filozoflar: dinî tecrübenin varoluşsal boyutuna ağırlık verir","y":["Mantıkçı pozitivistler: Tanrı’nın varlığına dair aklî delillere ağırlık verir","Akılcı filozoflar: din dilinin mantıkî çözümlemesine ağırlık verir","Tecrübeci filozoflar: ontolojik delilin ispatına ağırlık verir"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Felsefî yaklaşımlar","z":"orta","b":"Uygulama"},{"s":"Bir araştırma, dinin ahlâk ve sanatla ilişkisini inceleyip beşerî tecrübeleri organik bir bütünlüğe kavuşturmayı hedefliyor. Hangi problem kategorisindedir ve nasıl bir rol üstlenmektedir?","d":"İlişkisel problemler; din ile diğer alanlar arasında bağ kurma rolü","y":["Epistemolojik problemler; bilgi kaynaklarını sınıflandırma ve aralarında hiyerarşi kurma rolü","Sembolizm; dinî simgeleri çözümleme ve anlamlarını belirleme rolü","Metafizik problemler; âlemin yaratılışını ve düzenini açıklama rolü"],"t":60,"p":"2. hafta: Quiz (yeni, 15 soru)","k":"Ana problemler","z":"zor","b":"Analiz"}]$j$::jsonb) x
  where not exists (select 1 from public.questions q where q.subject_id = v_icerik and lower(q.soru) = lower(x->>'s'));
end $$;
